def rob(t, y):
    return [-0.04*y[0] + 1e4*y[1]*y[2], 0.04*y[0] - 1e4*y[1]*y[2] - 3e7*y[1]*y[1], 3e7*y[1]*y[1]]
def robj(t, y):
    return [[-0.04, 1e4*y[2], 1e4*y[1]],
            [0.04, -1e4*y[2] - 6e7*y[1], -1e4*y[1]],
            [0.0, 6e7*y[1], 0.0]]
def vdp(t, y): return [y[1], 1000.0*(1 - y[0]*y[0])*y[1] - y[0]]
def vdpj(t, y): return [[0.0, 1.0], [-2000.0*y[0]*y[1] - 1.0, 1000.0*(1 - y[0]*y[0])]]
def lin(t, y): return [-2.0*y[0] + y[1], y[0] - 2.0*y[1]]
LINJ = np.array([[-2.0, 1.0], [1.0, -2.0]])
def vdecay(t, y): return -0.5 * y
def cannon(t, y): return [y[1], -0.5]
class Hit:
    terminal: bool
    direction: float
    def __init__(self):
        self.terminal = True
        self.direction = -1.0
    def __call__(self, t, y):
        return y[0]

# ---------------------------------------------------------------- solve_ivp
def decay(t, y): return -0.5 * y
def osc(t, y): return [y[1], -y[0]]
def lv(t, z, a, b, c, d): return [a*z[0] - b*z[0]*z[1], -c*z[1] + d*z[0]*z[1]]
def apex(t, y): return y[1]

TOL = 1e-9
for case in IVP0:
    m, nfev, tref, yref = case
    s = I.solve_ivp(decay, [0, 10], [2, 4, 8], method=m)
    check(m + ' decay nfev', s.nfev == nfev)
    check(m + ' decay t', close(s.t, tref, TOL))
    check(m + ' decay y', close(s.y, yref, TOL))
    check(m + ' success', s.success and s.status == 0)
for case in IVP1:
    m, nfev, tref, yref = case
    s = I.solve_ivp(osc, (0.0, 20.0), [1.0, 0.0], method=m, rtol=1e-8, atol=1e-10)
    check(m + ' osc nfev', s.nfev == nfev)
    k = s.t.size
    check(m + ' osc t', close(s.t[k-3:], tref, 1e-7))
    check(m + ' osc y', close(s.y[:, k-1], yref, 1e-8))

s = I.solve_ivp(lv, [0, 15], [10, 5], args=(1.5, 1, 3, 1), dense_output=True)
check('lv', s.nfev == LV[0] and s.t.size == LV[1])
check('lv y', close(s.y[:, s.t.size-1], LV[2], TOL))
sol = s.sol
if sol is not None:
    check('lv sol', close(sol(7.3), LV[3], TOL))
    check('lv sol vec', close(sol(np.array([0.5, 14.0])), LV[4], TOL))
else:
    check('lv sol none', False)
s = I.solve_ivp(decay, [0, 10], [2.0], t_eval=[0, 1, 2.5, 10])
check('teval', s.nfev == TEVAL[0] and close(s.t, TEVAL[1]) and close(s.y, TEVAL[2], TOL))
s = I.solve_ivp(cannon, [0, 100], [0, 10], events=(Hit(), apex))
check('events status', s.status == EVENTS[0] and s.nfev == EVENTS[1])
check('events message', s.message == "A termination event occurred.")
check('events t', close(s.t[s.t.size-1], EVENTS[2], TOL))
check('events y', close(s.y[:, s.t.size-1], EVENTS[3], TOL, 1e-9))
check('events te', close(s.t_events[0], EVENTS[4], TOL) and close(s.t_events[1], EVENTS[5], TOL))
check('events ye', close(s.y_events[1], EVENTS[6], TOL, 1e-9))
s = I.solve_ivp(decay, [10, 0], [2.0], method='DOP853', dense_output=True, t_eval=[9.0, 3.0])
