s = I.solve_ivp(osc, [0, 5], [1.0, 0.0], method='RK23', dense_output=True, max_step=0.1,
                atol=[1e-6, 1e-8], first_step=0.01)
check('opts', s.nfev == OPTS[0] and s.t.size == OPTS[1] and close(s.y[:, s.t.size-1], OPTS[2], TOL))
sol = s.sol
if sol is not None:
    check('opts sol', close(sol(2.345), OPTS[3], TOL))
s = I.solve_ivp(osc, [0, 5], [1.0, 0.0], method='DOP853', dense_output=True)
sol = s.sol
check('dopdense nfev', s.nfev == DOPDENSE[0])
if sol is not None:
    check('dopdense', close(sol(1.234), DOPDENSE[1], TOL) and close(sol(4.9), DOPDENSE[2], TOL))
s = I.solve_ivp(decay, [0, 0], [1.0])
check('zero', s.nfev == ZERO[0] and close(s.t, ZERO[1]) and close(s.y, ZERO[2]) and s.status == ZERO[3])
for k in range(5):
    raised = False
    try:
        if k == 0:
            I.solve_ivp(decay, [0, 1], [1.0], method='Euler')
        elif k == 1:
            I.solve_ivp(decay, [0, 1], [1.0], t_eval=[0.5, 2.0])
        elif k == 2:
            I.solve_ivp(decay, [0, 1], [1.0], t_eval=[0.5, 0.2])
        elif k == 3:
            I.solve_ivp(decay, [0, 1], [1.0], max_step=-1.0)
        else:
            I.solve_ivp(decay, [0, 1], [1.0, 2.0], atol=[1e-6, 1e-6, 1e-6])
    except ValueError:
        raised = True
    check('ivp raises ' + str(k), raised)

if FAILS[0] == 0:
    print('integrate ivp ok')
